public class DateTimeTickUnitBase : IDateTimeUnit
{

    public (double[] Ticks, string[] Labels) GetTicksAndLabels(DateTime from, DateTime to, string format, Func<DateTime, string> manualDTConvertor = null)
    {
         DateTime[] ticks = GetTicks(from, to, deltas, maxTickCount);
         string[] labels;
